import { resolveColorModePreference } from "./resolveColorModePreference";

/**
 * NFR Design Pattern 1: resolves the color-mode preference synchronously and
 * applies it to the document root before the React tree mounts, so the CSS
 * custom properties generated by generateThemeCss are already correct at
 * first paint (FR-12 flash prevention).
 */
export function bootstrapColorMode(): void {
  if (typeof document === "undefined") {
    return;
  }

  const { value } = resolveColorModePreference();
  const root = document.documentElement;

  root.setAttribute("data-color-mode", value);
  root.classList.toggle("light", value === "light");
}
